// DeleteCustomer removes a customer outright, as if it had never been created (for undoing a create). The API deletes
// customers with SoftDeleteCustomer instead, so that their invoices keep them.
func (s *Store) DeleteCustomer(orgID, id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID {
		return ErrNotFound
	}
	delete(s.customers, id)
	s.unindexEmail(c)
	return nil
}

// SoftDeleteCustomer marks a customer deleted at now. Its email address is free again, and it can be restored within 30
// days. A customer with a subscription that is not canceled cannot be deleted.
func (s *Store) SoftDeleteCustomer(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrHasActiveSubscriptions
		}
	}
	at := now.UTC()
	c.DeletedAt = &at
	s.customers[id] = c
	s.unindexEmail(c)
	return nil
}

// RestoreCustomer undoes a soft delete made within the last 30 days. It fails with ErrEmailTaken when another of the
// organization's customers now uses the customer's email address.
func (s *Store) RestoreCustomer(orgID, id string, now time.Time) (Customer, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt == nil || now.Sub(*c.DeletedAt) > customerRestoreWindow {
		return Customer{}, ErrNotFound
	}
	key := normEmail(c.Email)
	if other, ok := s.customersByEmail[key]; ok && other != id && s.customers[other].OrgID == orgID {
		return Customer{}, ErrEmailTaken
	}
	c.DeletedAt = nil
	s.customers[id] = c
	s.customersByEmail[key] = id
	return copyCustomer(c), nil
}

// PurgeDeletedCustomers removes the customers deleted more than 30 days before now and returns how many it removed. Their
// invoices and payments stay, but no longer name a customer.
func (s *Store) PurgeDeletedCustomers(now time.Time) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, c := range s.customers {
		if c.DeletedAt != nil && now.Sub(*c.DeletedAt) > customerRestoreWindow {
			delete(s.customers, id)
			s.unindexEmail(c)
			n++
		}
	}
	return n
}

