func TestDeletedCustomers(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}, &sub)
	var inv struct {
		ID       string `json:"id"`
		Customer *struct {
			ID, Name, Email string
			Deleted         bool `json:"deleted"`
		} `json:"customer"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 1000}}}, &inv)

	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, &sub)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)

	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.deleted", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 1 {
		t.Fatalf("events = %+v", evs)
	}
	for _, req := range []struct {
		method, path string
		body         any
	}{
		{"GET", "/v1/customers/" + jane.ID, nil},
		{"PATCH", "/v1/customers/" + jane.ID, map[string]string{"name": "Jane Q"}},
		{"DELETE", "/v1/customers/" + jane.ID, nil},
		{"POST", "/v1/invoices", map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 100}}}},
		{"POST", "/v1/subscriptions", map[string]any{"customer_id": jane.ID, "plan_id": plan.ID}},
	} {
		if r := e.Do(req.method, req.path, e.Acme.Key, req.body); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
			t.Fatalf("%s %s on a deleted customer: %s", req.method, req.path, r)
		}
	}
	var page struct{ Items []store.Customer }
	for _, path := range []string{"/v1/customers", "/v1/customers?q=jane", "/v1/customers?email=Jane@example.com"} {
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("%s lists a deleted customer: %+v", path, page.Items)
		}
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil)
	if rows, err := csv.NewReader(strings.NewReader(string(r.Body))).ReadAll(); err != nil || len(rows) != 1 {
		t.Fatalf("csv = %v, %v", rows, err)
	}

	// The invoice keeps its customer, marked deleted.
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.ID != jane.ID || inv.Customer.Name != "Jane" || !inv.Customer.Deleted {
		t.Fatalf("invoice customer = %+v", inv.Customer)
	}

	// The email address is free again. Restoring Jane fails while another customer uses it.
	newJane := e.CreateCustomer(e.Acme, "Jane New", "jane@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email taken: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+newJane.ID, e.Acme.Key, map[string]any{"email": "jane.new@example.com"}, nil)
	var back store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &back)
	if back.ID != jane.ID || back.Email != "jane@example.com" {
		t.Fatalf("restored = %+v", back)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.Deleted {
		t.Fatalf("restored invoice customer = %+v", inv.Customer)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore of a customer that is not deleted: %s", r)
	}

	// After 30 days a deleted customer cannot be restored, and once purged its invoice names no customer.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("purged %d customers, want 1", n)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer != nil {
		t.Fatalf("purged customer on invoice = %+v", inv.Customer)
	}
}

